package ncasa.shoppinglist.application;
import java.util.*;import ncasa.shoppinglist.application.port.out.*;import ncasa.shoppinglist.domain.*;
public final class GetShoppingListUseCase{private final ShoppingListRepository lists;private final ShoppingItemRepository items;private final ShoppingListHouseholdAccessPort access;public GetShoppingListUseCase(ShoppingListRepository l,ShoppingItemRepository i,ShoppingListHouseholdAccessPort a){lists=l;items=i;access=a;}public ShoppingListDetail execute(Long actor,UUID household,UUID id){access.getContext(household,actor);var list=load(lists,id,household);return detail(list,items.list(id));}static ShoppingListDetail detail(ShoppingList list,List<ShoppingItem> all){return new ShoppingListDetail(list,all.stream().filter(x->x.status()==ShoppingItemStatus.PENDING).sorted(Comparator.comparingLong(ShoppingItem::position).thenComparing(ShoppingItem::id)).toList(),all.stream().filter(x->x.status()==ShoppingItemStatus.PURCHASED).sorted(Comparator.comparing(ShoppingItem::purchasedAt).thenComparing(ShoppingItem::id)).toList());}static ShoppingList load(ShoppingListRepository l,UUID id,UUID h){return l.find(id,h).orElseThrow(ShoppingListNotFoundException::new);}}
